Here's a complete example of data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline test cases ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpectedResult(int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.10, 90.00)]   // 10% off
    [DataRow(100.00, 0.00, 100.00)]  // no discount
    [DataRow(50.00, 0.50, 25.00)]    // 50% off
    [DataRow(200.00, 1.00, 0.00)]    // 100% off
    public void ApplyDiscount_ReturnsExpectedResult(double price, double discount, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: complex/reusable test cases ---

    [TestMethod]
    [DynamicData(nameof(CalculateTotalEdgeCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_EdgeCases_ReturnsExpectedResult(int quantity, decimal unitPrice, decimal expected)
    {
        var result = _calculator.CalculateTotal(quantity, unitPrice);
        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<object[]> CalculateTotalEdgeCases()
    {
        yield return new object[] { 1, 0.01m, 0.01m };         // smallest unit
        yield return new object[] { int.MaxValue, 0m, 0m };    // large qty, zero price
        yield return new object[] { 3, 33.33m, 99.99m };       // recurring decimal
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_InvalidInput_ThrowsArgumentException(decimal price, decimal discount)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discount));
    }

    public static IEnumerable<object[]> InvalidDiscountCases()
    {
        yield return new object[] { 100m, -0.1m };   // negative discount
        yield return new object[] { 100m, 1.5m };    // over 100%
        yield return new object[] { -10m, 0.1m };    // negative price
    }
}
```

**Key best practices shown:**

| Technique | When to use |
|-----------|-------------|
| `[DataRow]` | Simple inline values (primitives only) |
| `[DynamicData]` | Complex types, computed values, or shared datasets |
| `DynamicDataSourceType.Method` | Preferred over Property for lazy evaluation |

**Notes:**
- `DataRow` only supports compile-time constants (no `decimal` literals), so use `double` and cast.
- `DynamicData` methods support full `decimal`, custom objects, etc.
- Adapt the exception types/logic to match your actual validation implementation.
